      "sources": [
        {"quote":"本任务由 Morgan 负责组织","clause_id":"c1","occurrence":0,"context_anchor":null}
      ]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "文件是 verify 的直接对象。",
      "sources": [
        {"quote":"verify 隔离环境 中的 permission-6686.csv","clause_id":"c1","occurrence":0,"context_anchor":null}
